CREATE TABLE item_vectors (
    model_id  bigint NOT NULL,
    item_id   bigint NOT NULL,
    embedding vector NOT NULL,
    PRIMARY KEY (model_id, item_id)
);

CREATE INDEX item_vectors_m1 ON item_vectors
    USING hnsw ((embedding::vector(768)) vector_cosine_ops) WHERE (model_id = 1);
CREATE INDEX item_vectors_m2 ON item_vectors
    USING hnsw ((embedding::vector(1024)) vector_cosine_ops) WHERE (model_id = 2);

-- '[...]' stands for a full 768-value query vector from model 1
SELECT item_id FROM item_vectors WHERE model_id = 1
ORDER BY embedding::vector(768) <=> '[...]' LIMIT 10;

-- HNSW for cosine distance; give the build session more memory
SET maintenance_work_mem = '2GB';
CREATE INDEX chunks_embedding_hnsw ON chunks
    USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);

-- Or DiskANN on flexible server (allow-list pg_diskann first)
CREATE EXTENSION IF NOT EXISTS pg_diskann CASCADE;
CREATE INDEX chunks_embedding_diskann ON chunks
    USING diskann (embedding vector_cosine_ops);

-- More recall for one transaction only, then confirm the plan
BEGIN;
SET LOCAL hnsw.ef_search = 120;
EXPLAIN (ANALYZE, BUFFERS)
-- '[0.12, 0.05, ...]' stands for a full 1,536-value query vector
SELECT id FROM chunks ORDER BY embedding <=> '[0.12, 0.05, ...]' LIMIT 5;
COMMIT;

pgvector ranks rows with ORDER BY distance and LIMIT k. Cosine distance from <=> runs from 0 (same direction) to 2, so the smallest distances come first. With an approximate index, PostgreSQL applies the WHERE filter after the index scan, so a selective filter can leave fewer rows than LIMIT asked for. The pgvector README lists remedies:
• an ordinary index on the filter column (B-tree by default) for fast exact search when the filter matches a low percentage of rows, or a multicolumn index for several filter columns;
• a partial index when queries filter on a few distinct values;
• partitioning when they filter on many values; list partitioning, or separate tables, also isolates tenants so one tenant's vectors don't affect another's recall;
• a wider search list, or for DiskANN its iterative search.

import json
import logging

import azure.functions as func

app = func.FunctionApp()


@app.route(route="reports", methods=["POST"], auth_level=func.AuthLevel.FUNCTION)
@app.service_bus_queue_output(arg_name="job", queue_name="reports",
                              connection="ServiceBusConnection")
def request_report(req: func.HttpRequest, job: func.Out[str]) -> func.HttpResponse:
    try:
        body = req.get_json()
    except ValueError:
        return func.HttpResponse("expected JSON", status_code=400)
    job.set(json.dumps({"reportId": body["reportId"]}))
    return func.HttpResponse(status_code=202)  # accepted; built in the background


@app.service_bus_queue_trigger(arg_name="msg", queue_name="reports",
                               connection="ServiceBusConnection")
def build_report(msg: func.ServiceBusMessage) -> None:
    job = json.loads(msg.get_body().decode())
    logging.info("building report %s", job["reportId"])


@app.timer_trigger(arg_name="timer", schedule="0 30 2 * * *")  # 02:30 UTC every day
def nightly_cleanup(timer: func.TimerRequest) -> None:
    if timer.past_due:
        logging.warning("timer ran late")

